import 'package:flutter/material.dart';
import 'package:image_picker/image_picker.dart';
import '../models/animal.dart';
import '../services/animal_service.dart';
import '../services/imagem_service.dart';
import '../widgets/foto_animal.dart';
class AnimalForm extends StatefulWidget {final Animal? animal;const AnimalForm({super.key,this.animal});@override State<AnimalForm> createState()=>_AnimalFormState();}
class _AnimalFormState extends State<AnimalForm>{
 final form=GlobalKey<FormState>(); final nome=TextEditingController(),raca=TextEditingController(),idade=TextEditingController(),descricao=TextEditingController();
 String especie='Cachorro',porte='Pequeno',sexo='Macho',foto='';bool vacinado=false,castrado=false,ocupado=false;
 @override void initState(){super.initState();final d=widget.animal?.dados;if(d!=null){nome.text=d['nome'];raca.text=d['raca'];idade.text=d['idadeMeses'].toString();descricao.text=d['descricao'];especie=d['especie'];porte=d['porte'];sexo=d['sexo'];foto=d['fotoBase64']??'';vacinado=d['vacinado'];castrado=d['castrado'];}}
 @override void dispose(){for(final c in [nome,raca,idade,descricao]){c.dispose();}super.dispose();}
 Future<void> tarefa(Future<void> Function() fn) async {if(ocupado)return;setState(()=>ocupado=true);try{await fn();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>ocupado=false);}}
 Future<void> selecionar(ImageSource origem)=>tarefa(() async {final f=await ImagemService().selecionar(origem);if(mounted&&f!=null)setState(()=>foto=f);});
 Future<void> salvar() async {if(!form.currentState!.validate())return;await tarefa(() async {await AnimalService().salvar({'nome':nome.text.trim(),'raca':raca.text.trim(),'idadeMeses':int.parse(idade.text.trim()),'descricao':descricao.text.trim(),'especie':especie,'porte':porte,'sexo':sexo,'vacinado':vacinado,'castrado':castrado,'fotoBase64':foto},id:widget.animal?.id);if(mounted)Navigator.pop(context);});}
 Widget campo(String label,TextEditingController c,int max,{bool obrigatorio=true})=>Padding(padding:const EdgeInsets.symmetric(vertical:6),child:TextFormField(controller:c,maxLength:max,enabled:!ocupado,keyboardType:c==idade?TextInputType.number:TextInputType.text,decoration:InputDecoration(labelText:label),validator:(v){if(c==idade&&((int.tryParse(v?.trim()??'')??-1)<0))return 'Idade inválida';if(obrigatorio&&(v??'').trim().isEmpty)return 'Campo obrigatório';return null;}));
 Widget escolha(String label,String valor,List<String> itens,void Function(String) mudar)=>DropdownButtonFormField<String>(initialValue:valor,decoration:InputDecoration(labelText:label),items:itens.map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:ocupado?null:(v)=>setState(()=>mudar(v!)));
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.animal==null?'Cadastrar animal':'Editar animal')),body:Form(key:form,child:ListView(padding:const EdgeInsets.all(16),children:[FotoAnimal(fotoBase64:foto),Wrap(children:[TextButton(onPressed:ocupado?null:()=>selecionar(ImageSource.gallery),child:const Text('Galeria')),TextButton(onPressed:ocupado?null:()=>selecionar(ImageSource.camera),child:const Text('Câmera')),TextButton(onPressed:ocupado?null:()=>setState(()=>foto=''),child:const Text('Remover foto'))]),campo('Nome',nome,100),escolha('Espécie',especie,['Cachorro','Gato','Outro'],(v)=>especie=v),campo('Raça',raca,100,obrigatorio:false),campo('Idade em meses',idade,6),escolha('Porte',porte,['Pequeno','Médio','Grande'],(v)=>porte=v),const SizedBox(height:12),escolha('Sexo',sexo,['Macho','Fêmea'],(v)=>sexo=v),campo('Descrição',descricao,2000),CheckboxListTile(title:const Text('Vacinado'),value:vacinado,onChanged:ocupado?null:(v)=>setState(()=>vacinado=v!)),CheckboxListTile(title:const Text('Castrado'),value:castrado,onChanged:ocupado?null:(v)=>setState(()=>castrado=v!)),if(ocupado)const LinearProgressIndicator()else FilledButton(onPressed:salvar,child:const Text('Salvar e enviar para aprovação'))])));
}
